190	impl Body {
191	    /// Whether the body's evidence is complete, so that a prop it never mentions is known to be unused: nothing handed
192	    /// on, and no spread of the props onto a tag that did not resolve. What an incomplete body does say (a read, a
193	    /// default, a forward) is still certain; only its silence is unknown.
194	    fn is_complete(&self) -> bool {
195	        !self.handed_on
196	            && !self.elements.iter().any(|element| {
197	                element.target == Target::Unresolved
198	                    && element.attributes.iter().any(|attribute| attribute.spreads_props())
199	            })
200	    }
201	
202	    /// The props a spread of the props object or a rest binding passes one hop on to a component: the component's own
203	    /// props, minus those an attribute after the spread fixes. Spreads onto DOM tags pass nothing.
204	    fn forwarded(&self) -> BTreeSet<&str> {
205	        let mut forwarded = BTreeSet::new();
206	        for element in &self.elements {
207	            let Target::Component(own) = &element.target else { continue };
208	            for (at, attribute) in element.attributes.iter().enumerate() {
209	                if !attribute.spreads_props() {
210	                    continue;
211	                }
212	                let fixed: BTreeSet<&str> = element.attributes[at + 1..]
213	                    .iter()
214	                    .filter_map(|after| match after {
215	                        Attribute::Named { name, .. } => Some(name.as_str()),
216	                        Attribute::Spread(_) => None,
217	                    })
218	                    .collect();
219	                forwarded.extend(own.iter().map(String::as_str).filter(|name| !fixed.contains(name)));
220	            }
221	        }
222	        forwarded
223	    }
224	}
